import { Flow, wfa, trigger } from '@servicenow/sdk/automation'

Flow(
    {
        $id: Now.ID['test_skip_iteration_flow_logic'],
        name: 'Test-Skip-Iteration-Flow-Logic',
        runAs: 'user',
    },
    wfa.trigger(
        trigger.record.created,
        {
            $id: Now.ID['test_skip_iteration_flow_logic_trigger'],
        },
        {
            table: 'incident',
            condition: '^EQ',
            run_on_extended: 'false',
            run_flow_in: 'any',
            run_when_user_list: [],
            run_when_setting: 'both',
            run_when_user_setting: 'any',
        }
    ),
    (_params) => {
        wfa.flowLogic.forEach(
            wfa.dataPill(_params.trigger.current.additional_assignee_list, 'array.string'),
            {
                annotation: 'Iterate through additional assignee list',
                $id: Now.ID['test_skip_iteration_flow_logic_for_each_1'],
            },
            () => {
                wfa.flowLogic.if(
                    {
                        condition: `${wfa.dataPill(_params.trigger.current.active, 'boolean')}=false`,
                        annotation: 'Check if active is false',
                        $id: Now.ID['test_skip_iteration_flow_logic_if_1'],
                    },
                    () => {
                        wfa.flowLogic.skipIteration({
                            annotation: 'Skip iteration',
                            $id: Now.ID['test_skip_iteration_flow_logic_skip_iteration_1'],
                        })
                    }
                )
            }
        )
        wfa.flowLogic.forEach(
            wfa.dataPill(_params.trigger.current.work_notes_list, 'array.string'),
            {
                annotation: 'Iterate through work notes list',
                $id: Now.ID['test_skip_iteration_flow_logic_for_each_2'],
            },
            () => {
                wfa.flowLogic.forEach(
                    wfa.dataPill(_params.trigger.current.additional_assignee_list, 'array.string'),
                    {
                        annotation: 'Iterate through additional assignee list',
                        $id: Now.ID['test_skip_iteration_flow_logic_for_each_3'],
                    },
                    () => {
                        wfa.flowLogic.if(
                            {
                                condition: `${wfa.dataPill(_params.trigger.current.additional_assignee_list, 'reference')}ISEMPTY`,
                                annotation: 'Check if additional assignee list is empty',
                                $id: Now.ID['test_skip_iteration_flow_logic_if_2'],
                            },
                            () => {
                                wfa.flowLogic.skipIteration({
                                    annotation: 'Skip iteration',
                                    $id: Now.ID['test_skip_iteration_flow_logic_skip_iteration_2'],
                                })
                            }
                        )
                    }
                )
            }
        )
        wfa.flowLogic.if(
            {
                condition: `${wfa.dataPill(_params.trigger.current.additional_assignee_list, 'reference')}ISEMPTY`,
                annotation: 'Check if additional assignee list is empty',
                $id: Now.ID['test_skip_iteration_flow_logic_if_3'],
            },
            () => {
                wfa.flowLogic.forEach(
                    wfa.dataPill(_params.trigger.current.work_notes_list, 'array.string'),
                    {
                        annotation: 'Iterate through work notes list',
                        $id: Now.ID['test_skip_iteration_flow_logic_for_each_4'],
                    },
                    () => {
                        wfa.flowLogic.if(
                            {
                                condition: `${wfa.dataPill(_params.trigger.current.priority, 'string')}=1`,
                                annotation: 'Check if priority is 1',
                                $id: Now.ID['test_skip_iteration_flow_logic_if_4'],
                            },
                            () => {
                                wfa.flowLogic.skipIteration({
                                    annotation: 'Skip iteration',
                                    $id: Now.ID['test_skip_iteration_flow_logic_skip_iteration_3'],
                                })
                            }
                        )
                    }
                )
            }
        )
        wfa.flowLogic.forEach(
            wfa.dataPill(_params.trigger.current.additional_assignee_list, 'array.string'),
            {
                annotation: 'Iterate through additional assignee list - nested if test',
                $id: Now.ID['test_skip_iteration_flow_logic_for_each_5'],
            },
            () => {
                wfa.flowLogic.if(
                    {
                        condition: `${wfa.dataPill(_params.trigger.current.active, 'boolean')}=true`,
                        annotation: 'Check if active is true',
                        $id: Now.ID['test_skip_iteration_flow_logic_if_5'],
                    },
                    () => {
                        wfa.flowLogic.if(
                            {
                                condition: `${wfa.dataPill(_params.trigger.current.priority, 'string')}=1`,
                                annotation: 'Check if priority is 1 (nested)',
                                $id: Now.ID['test_skip_iteration_flow_logic_if_6'],
                            },
                            () => {
                                wfa.flowLogic.skipIteration({
                                    annotation: 'Skip iteration from nested if',
                                    $id: Now.ID['test_skip_iteration_flow_logic_skip_iteration_4'],
                                })
                            }
                        )
                    }
                )
            }
        )
    }
)
